// Bestätigter Arztbrief – Entscheidung: Der Brief gelangt nur dann in das RAG (verlässlich), wenn die Kontrollregeln darin KEINEN Widerspruch gefunden haben.
// Ein Brief mit Widerspruch bleibt „zu prüfen“, bis der Arzt ihn geklärt hat; die Bestätigung des Berichts wird nur festgehalten.
const v = $input.first().json ?? {};
if (!v.validation_id) return [{ json: { ajouter: false, motif: 'Bestätigung nicht gefunden oder ohne Prüfbericht' } }];
if (!/^kim\/[^\s]{1,200}$/.test(String(v.lettre_ref ?? ''))) return [{ json: { ajouter: false, motif: 'Kein Schreiben mit diesem Bericht verknüpft', patient_id: v.patient_id } }];
if (v.sans_contradiction !== true) return [{ json: { ajouter: false, motif: 'Widerspruch mit dem Arzt zu klären: Das Schreiben bleibt zu prüfen', patient_id: v.patient_id, lettre_ref: v.lettre_ref } }];
return [{ json: { ajouter: true, patient_id: v.patient_id, lettre_ref: v.lettre_ref, validation_id: v.validation_id } }];

// Bestätigter Arztbrief – setzt den Brief aus seinen Abschnitten (Collection « a_verifier ») wieder zusammen, um ihn zu « patients » hinzuzufügen.
// Typ « lettre_validee »: unterscheidet sich von « lettre » (der Fingerabdruck im Importprotokoll wird nicht mit dem der zu prüfenden Version verwechselt).
const d = $('Entscheiden').first().json;
const points = ($input.first().json?.result?.points ?? []).map((p) => p.payload).sort((a, b) => a.chunk_index - b.chunk_index);
if (!points.length) throw new Error('Schreiben in « a_verifier » nicht gefunden');
const p0 = points[0];
if (p0.patient_id !== d.patient_id) throw new Error('Der Bewohner des Schreibens stimmt nicht mit dem der Bestätigung überein');
return [
  {
    json: {
      collection: 'patients',
      source: 'kim',
      source_label: 'KIM (Arztbrief)',
      source_ref: p0.source_ref,
      type: 'lettre_validee',
      titre: `${p0.titre} (bestätigt)`,
      expediteur: p0.expediteur,
      patient_id: p0.patient_id,
      chambre: p0.chambre,
      statut: 'valide',
      texte: points.map((p) => p.texte).join('\n'),
      date: p0.date,
    },
  },
];

// Bestätigter Arztbrief – an den Aufrufer zurückgegebenes Ergebnis und Audit-Ereignis.
const d = $('Entscheiden').first().json;
const ajoutee = d.ajouter === true;
return [
  {
    json: {
      lettre: { ajoutee, motif: ajoutee ? 'Bestätigter Arztbrief zu den Wissensquellen hinzugefügt' : d.motif },
      evenement_journal: {
        evenement: ajoutee ? 'lettre_validee' : 'lettre_non_ajoutee',
        patient_id: d.patient_id ?? null,
        mode: 'a',
        action: 'verifier_document',
        details: { lettre: d.lettre_ref ?? null, motif: ajoutee ? 'ajoutee' : d.motif },
      },
    },
  },
];

// Bestätigter Arztbrief – Ausgang des Unter-Workflows (ohne das Protokollereignis).
const { evenement_journal, ...r } = $('Ergebnis').first().json;
return [{ json: r }];
